        else
            printf("Unknown command: %s (type 'help')\n", cmd);

        pthread_mutex_lock(&g_stdout_lock);
        printf("vela> ");
        fflush(stdout);
        pthread_mutex_unlock(&g_stdout_lock);
    }

    syslog(LOG_INFO, "[%s] CLI thread exiting\n", TAG);
