        else if (strcmp(cmd, "config_show") == 0)
            cmd_config_show();
        else if (strcmp(cmd, "config_reset") == 0)
            cmd_config_reset();
        else if (strcmp(cmd, "heartbeat_trigger") == 0)
            cmd_heartbeat_trigger();
        else if (strcmp(cmd, "ask") == 0)
            cmd_ask(argc, argv);
        else if (strcmp(cmd, "cron_start") == 0)
