 49	static int simple_entropy_func(void* data, unsigned char* output, size_t len)
 50	{
 51	    (void)data;
 52	    if (agent_secure_random(output, len) == 0) {
 53	        return 0;
 54	    }
 55	    /* No fallback — cryptographic entropy is mandatory for TLS.
 56	     * Returning an error forces the TLS handshake to fail safely
 57	     * rather than proceeding with predictable key material. */
 58	    syslog(LOG_ERR, "[vela_tls] CRITICAL: No secure entropy source available\n");
 59	    return -1;  /* Generic error - TLS handshake will fail safely */
 60	}
