 64	/* ── Chunked transfer decoding ───────────────────────────────── */
 65	
 66	/**
 67	 * Decode chunked transfer encoding in-place.
 68	 * Format: <hex-size>\r\n<data>\r\n ... 0\r\n\r\n
 69	 * Returns the decoded length.
 70	 */
 71	static size_t decode_chunked(char* buf, size_t len)
 72	{
 73	    char* src = buf;
 74	    char* end = buf + len;
 75	    char* dst = buf;
 76	
 77	    while (src < end) {
 78	        /* Find end of chunk-size line */
 79	        char* crlf = (char*)memmem(src, (size_t)(end - src), "\r\n", 2);
 80	        if (!crlf)
 81	            break;
 82	
 83	        /* Parse hex chunk size */
 84	        char* endptr;
 85	        long chunk_sz = strtol(src, &endptr, 16);
 86	
 87	        /* Validate: endptr should reach the CRLF (skip spaces) */
 88	        while (endptr < crlf && *endptr == ' ')
 89	            endptr++;
 90	
 91	        if (endptr != crlf || chunk_sz < 0 || chunk_sz > (long)(end - crlf - 2))
 92	            break;  /* malformed or oversized chunk header */
 93	
 94	        if (chunk_sz == 0)
 95	            break;  /* final chunk */
 96	
 97	        src = crlf + 2;  /* skip past chunk-size CRLF */
 98	
 99	        /* Clamp to available data */
100	        if (src + chunk_sz > end)
101	            chunk_sz = (long)(end - src);
102	
103	        memmove(dst, src, (size_t)chunk_sz);
104	        dst += chunk_sz;
105	        src += chunk_sz;
106	
107	        /* Skip trailing CRLF after chunk data */
108	        if (src + 2 <= end && src[0] == '\r' && src[1] == '\n')
109	            src += 2;
110	    }
111	
112	    return (size_t)(dst - buf);
113	}
