138	/* ── Persistent connection pool (keep-alive) ─────────────────── */
139	/* Keeps one live TLS connection per host:port so repeated calls to
140	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
141	
142	#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
143	#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
144	#else
145	#define CONN_POOL_SIZE 2
146	#endif
147	
148	typedef struct {
149	    tls_ctx_t ctx;
150	    char host[128];
151	    char port[8];
152	    bool in_use; /* locked by a request */
153	    bool valid; /* connection is alive */
154	} conn_slot_t;
155	
156	static conn_slot_t s_pool[CONN_POOL_SIZE];
157	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
158	
159	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
160	static conn_slot_t* pool_acquire(const char* host, const char* port)
161	{
162	    pthread_mutex_lock(&s_pool_lock);
163	
164	    /* 1. Find an existing valid slot for this host:port */
165	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
166	        conn_slot_t* s = &s_pool[i];
167	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
168	            s->in_use = true;
169	            pthread_mutex_unlock(&s_pool_lock);
170	            return s;
171	        }
172	    }
173	
174	    /* 2. Find an empty slot */
175	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
176	        if (!s_pool[i].valid && !s_pool[i].in_use) {
177	            s_pool[i].in_use = true;
178	            pthread_mutex_unlock(&s_pool_lock);
179	            return &s_pool[i];
180	        }
181	    }
182	
183	    /* 3. Evict the first non-in-use slot */
184	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
185	        if (!s_pool[i].in_use) {
186	            tls_ctx_free(&s_pool[i].ctx);
187	            s_pool[i].valid = false;
188	            s_pool[i].in_use = true;
189	            pthread_mutex_unlock(&s_pool_lock);
190	            return &s_pool[i];
191	        }
192	    }
193	
194	    pthread_mutex_unlock(&s_pool_lock);
195	    return NULL; /* all slots busy — caller falls back to ephemeral */
196	}
197	
198	/* Return a slot to the pool.  keep=true means the connection is still alive. */
199	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
200	{
201	    pthread_mutex_lock(&s_pool_lock);
202	    if (keep) {
203	        strncpy(s->host, host, sizeof(s->host) - 1);
204	        strncpy(s->port, port, sizeof(s->port) - 1);
205	        s->valid = true;
206	    } else {
207	        tls_ctx_free(&s->ctx);
208	        s->valid = false;
209	        s->host[0] = '\0';
210	    }
211	    s->in_use = false;
212	    pthread_mutex_unlock(&s_pool_lock);
213	}
214	
215	void vela_tls_pool_cleanup(void)
216	{
217	    pthread_mutex_lock(&s_pool_lock);
218	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
219	        if (s_pool[i].in_use) {
220	            syslog(LOG_WARNING,
221	                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
222	            continue;
223	        }
224	        if (s_pool[i].valid) {
225	            tls_ctx_free(&s_pool[i].ctx);
226	            s_pool[i].valid = false;
227	        }
228	        s_pool[i].host[0] = '\0';
229	    }
230	    pthread_mutex_unlock(&s_pool_lock);
231	}
232	
233	static int tls_ctx_connect(tls_ctx_t* ctx, const char* host, const char* port)
234	{
235	    int ret;
236	
237	    mbedtls_ssl_init(&ctx->ssl);
238	    mbedtls_ssl_config_init(&ctx->cfg);
239	    mbedtls_net_init(&ctx->net);
240	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
241	
242	    /* Seed RNG directly with our robust function */
243	    const char* pers = "vela_tls";
244	    if ((ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, simple_entropy_func, NULL,
245	             (const unsigned char*)pers,
246	             strlen(pers)))
247	        != 0) {
248	        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=0x%x\n", TAG, -ret);
249	        return VELA_TLS_ERR_HANDSHAKE;
250	    }
251	
252	    /* Check system time — crucial for TLS certificate validation. */
253	    time_t now = time(NULL);
254	    syslog(LOG_DEBUG, "[%s] Handshake start: Host=%s, UNIX=%ld\n", TAG, host, (long)now);
255	
256	    if (now < 1704067200) { /* Jan 1 2024 */
257	        syslog(LOG_WARNING, "[%s] Clock too old, forcing to 2026\n", TAG);
258	        struct timespec ts = { .tv_sec = 1772275200, .tv_nsec = 0 };
259	        clock_settime(CLOCK_REALTIME, &ts);
260	    }
261	
262	    /* TCP connect — use HTTP CONNECT proxy if configured */
263	#ifdef CONFIG_AI_AGENT_NET_RPMSG
264	    {
265	        int res_ret = network_acquire_resource(network_get_connect_timeout() * 1000);
266	        if (res_ret != 0) {
267	            syslog(LOG_ERR, "[%s] Resource acquire failed: %d\n", TAG, res_ret);
268	            return VELA_TLS_ERR_CONNECT;
269	        }
270	    }
271	#endif
272	
273	    if (http_proxy_is_enabled()) {
274	        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
275	        if (tunnel_fd < 0) {
276	            syslog(LOG_ERR, "[%s] proxy tunnel to %s:%s failed\n",
277	                TAG, host, port);
278	            return VELA_TLS_ERR_CONNECT;
279	        }
280	        ctx->net.fd = tunnel_fd;
281	        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
282	            TAG, tunnel_fd, host, port);
283	    } else {
284	        if ((ret = mbedtls_net_connect(&ctx->net, host, port,
285	                 MBEDTLS_NET_PROTO_TCP))
286	            != 0) {
287	            syslog(LOG_ERR, "[%s] net_connect %s:%s ret=0x%x\n",
288	                TAG, host, port, -ret);
289	            return VELA_TLS_ERR_CONNECT;
290	        }
291	    }
292	
293	    /* Force blocking mode and set socket-level read timeout.
294	     * This avoids using select()/poll() inside mbedtls_net_recv_timeout
295	     * which returns MBEDTLS_ERR_NET_POLL_FAILED (-0x0047) on NuttX/QEMU.
296	     * Timeout is configured via AGENT_LLM_SOCKET_TIMEOUT_SEC in
297	     * agent_config.h.  LLM APIs (especially kimi with thinking mode)
298	     * can take over 60s for long responses. */
299	    mbedtls_net_set_block(&ctx->net);
300	    if (ctx->net.fd >= 0) {
301	#ifdef CONFIG_AI_AGENT_NET_RPMSG
302	        int read_timeout_sec = network_get_read_timeout();
303	        struct timeval tv = { .tv_sec = read_timeout_sec, .tv_usec = 0 };
304	#else
305	        struct timeval tv = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
306	            .tv_usec = 0 };
307	#endif
308	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
309	
310	#ifdef CONFIG_AI_AGENT_NET_RPMSG
311	        {
312	            int timeout_sec = network_get_connect_timeout();
313	            struct timeval ctv = { .tv_sec = timeout_sec, .tv_usec = 0 };
314	            setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));
315	        }
316	#endif
317	    }
318	
319	    /* SSL config: client, TLS, default ciphersuites */
320	    if ((ret = mbedtls_ssl_config_defaults(&ctx->cfg,
321	             MBEDTLS_SSL_IS_CLIENT,
322	             MBEDTLS_SSL_TRANSPORT_STREAM,
323	             MBEDTLS_SSL_PRESET_DEFAULT))
324	        != 0) {
325	        syslog(LOG_ERR, "[%s] ssl_config_defaults ret=0x%x\n", TAG, -ret);
326	        return VELA_TLS_ERR_HANDSHAKE;
327	    }
328	
329	    /* Pin the TLS version range to what is actually compiled in.
330	     * Setting max to MBEDTLS_SSL_VERSION_TLS1_3 when MBEDTLS_SSL_PROTO_TLS1_3
331	     * is not defined causes mbedtls_ssl_setup() to return BAD_CONFIG (-0x5e80).
332	     * Use TLS 1.3 as the ceiling only when the library was built with TLS 1.3
333	     * support; otherwise cap at TLS 1.2. */
334	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
335	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
336	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
337	#else
338	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
339	#endif
340	
341	    /* Advertise ALPN so Cloudflare/OpenAI servers don't silently reject us.
342	     * Modern HTTPS servers send a fatal TLS alert or close the connection
343	     * when no ALPN extension is present in the ClientHello.
344	     * MBEDTLS_SSL_ALPN must be enabled in the build (it is). */
345	#if defined(MBEDTLS_SSL_ALPN)
346	    static const char* alpn_protos[] = { "http/1.1", NULL };
347	    if ((ret = mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn_protos)) != 0) {
348	        syslog(LOG_WARNING, "[%s] Failed to set ALPN protocols: -0x%04x (non-fatal)\n", TAG, -ret);
349	    }
350	#endif
351	
352	    /* Skip full chain verification — keeps portability without CA bundle */
353	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
354	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);
355	
356	    /* Read timeout is handled at the socket level via SO_RCVTIMEO,
357	     * not via mbedtls_ssl_conf_read_timeout + mbedtls_net_recv_timeout,
358	     * because select()/poll() inside mbedtls_net_recv_timeout fails on
359	     * NuttX/QEMU with MBEDTLS_ERR_NET_POLL_FAILED (-0x0047). */
360	
361	    if ((ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg)) != 0) {
362	        syslog(LOG_ERR, "[%s] ssl_setup ret=0x%x\n", TAG, -ret);
363	        return VELA_TLS_ERR_HANDSHAKE;
364	    }
365	
366	    if ((ret = mbedtls_ssl_set_hostname(&ctx->ssl, host)) != 0) {
367	        syslog(LOG_ERR, "[%s] ssl_set_hostname ret=0x%x\n", TAG, -ret);
368	        return VELA_TLS_ERR_HANDSHAKE;
369	    }
370	
371	    /* Use blocking recv — no select()/poll().  The read
372	     * timeout is enforced by the SO_RCVTIMEO socket option set above. */
373	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
374	        mbedtls_net_send, mbedtls_net_recv, NULL);
375	
376	    /* Handshake */
377	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
378	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
379	#if defined(MBEDTLS_ERROR_C)
380	            char err_buf[128];
381	            mbedtls_strerror(ret, err_buf, sizeof(err_buf));
382	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x: %s\n", TAG, -ret, err_buf);
383	#else
384	            syslog(LOG_ERR, "[%s] ssl_handshake ret=-0x%04x\n", TAG, -ret);
385	#endif
386	            /* Log if it was a fatal alert */
387	            if (ret == MBEDTLS_ERR_SSL_FATAL_ALERT_MESSAGE) {
388	                syslog(LOG_ERR, "[%s] Server sent fatal alert message\n", TAG);
389	            }
390	            return VELA_TLS_ERR_HANDSHAKE;
391	        }
392	    }
393	
394	    syslog(LOG_INFO, "[%s] Handshake OK: %s / %s\n", TAG, mbedtls_ssl_get_version(&ctx->ssl),
395	        mbedtls_ssl_get_ciphersuite(&ctx->ssl));
396	    syslog(LOG_INFO, "[ASK-DIAG] tls handshake ok\n");
397	    syslog(LOG_INFO, "[TLS-PROBE] handshake ok\n");
398	
399	    return 0;
400	}
