402	/* ── HTTP/1.1 framing ────────────────────────────────────────── */
403	
404	static int tls_write_request(tls_ctx_t* ctx,
405	    const char* method, const char* host,
406	    const char* path,
407	    const vela_header_t* headers,
408	    const char* body, size_t body_len)
409	{
410	    /* Heap-allocate header buffer to reduce stack pressure.
411	     * This function is called from threads with limited stack
412	     * (outbound dispatch 16KB) and the TLS context already
413	     * consumes significant stack space. */
414	    char* hdr = malloc(4096);
415	    if (!hdr)
416	        return VELA_TLS_ERR_OVERFLOW;
417	
418	    int pos = 0;
419	    int ret;
420	
421	#define HDR_APPEND(fmt, ...)                                    \
422	    pos += snprintf(hdr + pos, 4096 - pos, fmt, ##__VA_ARGS__); \
423	    if (pos >= 4096) {                                          \
424	        free(hdr);                                              \
425	        return VELA_TLS_ERR_OVERFLOW;                           \
426	    }
427	
428	    HDR_APPEND("%s %s HTTP/1.1\r\n", method, path);
429	    HDR_APPEND("Host: %s\r\n", host);
430	    HDR_APPEND("Connection: keep-alive\r\n");

   675	int vela_https_request(
   676	    const char* host,
   677	    const char* port,
   678	    const char* method,
   679	    const char* path,
   680	    const vela_header_t* headers,
   681	    const char* body,
   682	    size_t body_len,
   683	    char* resp_buf,
   684	    size_t resp_cap,
   685	    size_t* out_body_len)
   686	{
   687	    int ret;
   688	
   689	    /* Try to get a pooled connection first */
   690	    conn_slot_t* slot = pool_acquire(host, port);
   691	
   692	    if (slot && slot->valid) {
   693	        /* Drain any leftover data from previous response before reuse.
   694	         * Without this, a partially-read response body (e.g. truncated
   695	         * chunked data) would be misinterpreted as the next HTTP status. */
   696	        if (slot->ctx.net.fd >= 0) {
   697	            unsigned char drain[512];
   698	            int dr;
   699	            /* Temporarily set a very short socket timeout to drain without blocking */
   700	            struct timeval tv_drain = { .tv_sec = 0, .tv_usec = 10000 }; /* 10ms */
   701	            struct timeval tv_orig = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
   702	                .tv_usec = 0 };
   703	            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
   704	                &tv_drain, sizeof(tv_drain));
   705	            while ((dr = mbedtls_ssl_read(&slot->ctx.ssl, drain, sizeof(drain))) > 0)
   706	                ; /* discard leftover bytes */
   707	            /* Restore original timeout */
   708	            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
   709	                &tv_orig, sizeof(tv_orig));
   710	            /* If peer closed the connection, reconnect */
   711	            if (dr == 0 || dr == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
   712	                goto pool_reconnect;
   713	            }
   714	        } else {
   715	            goto pool_reconnect;
   716	        }
   717	
   718	        /* Reuse existing connection — skip TLS handshake */
   719	        syslog(LOG_DEBUG, "[%s] Reusing pooled connection to %s:%s\n", TAG, host, port);
   720	        ret = tls_write_request(&slot->ctx, method, host, path, headers, body, body_len);
   721	        if (ret == 0) {
   722	            bool keep = false;
   723	            ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, out_body_len, &keep);
   724	            if (ret > 0) {
   725	                pool_release(slot, host, port, keep);
   726	                return ret;
   727	            }
   728	        }
   729	        /* Connection went stale — fall through to reconnect */
   730	    pool_reconnect:
   731	        syslog(LOG_INFO, "[%s] Pooled connection stale, reconnecting\n", TAG);
   732	        tls_ctx_free(&slot->ctx);
   733	        slot->valid = false;
   734	    }
   735	
   736	    /* New connection */
   737	    if (!slot) {
   738	        /* Pool full — use a temporary ephemeral context */
   739	        tls_ctx_t tmp_ctx;
   740	        if ((ret = tls_ctx_connect(&tmp_ctx, host, port)) != 0) {
   741	            tls_ctx_free(&tmp_ctx);
   742	            return ret;
   743	        }
   744	        if ((ret = tls_write_request(&tmp_ctx, method, host, path,
   745	                 headers, body, body_len))
   746	            != 0) {
   747	            syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
   748	            tls_ctx_free(&tmp_ctx);
   749	            return ret;
   750	        }
   751	        ret = tls_read_response(&tmp_ctx, resp_buf, resp_cap, out_body_len, NULL);
   752	        tls_ctx_free(&tmp_ctx);
   753	        return ret;
   754	    }
   755	
   756	    /* Connect into the slot */
   757	    if ((ret = tls_ctx_connect(&slot->ctx, host, port)) != 0) {
   758	        pool_release(slot, host, port, false);
   759	        return ret;
   760	    }
   761	
   762	    if ((ret = tls_write_request(&slot->ctx, method, host, path,
   763	             headers, body, body_len))
   764	        != 0) {
   765	        syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
   766	        pool_release(slot, host, port, false);
   767	        return ret;
   768	    }
   769	
   770	    bool keep = false;
   771	    ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, out_body_len, &keep);
   772	    pool_release(slot, host, port, ret > 0 && keep);
   773	    return ret;
   774	}
