   776	int vela_https_get(const char* host, const char* port, const char* path,
   777	    char* resp_buf, size_t resp_cap)
   778	{
   779	    return vela_https_request(host, port, "GET", path, NULL, NULL, 0,
   780	        resp_buf, resp_cap, NULL);
   781	}
