   783	int vela_https_post_json(const char* host, const char* port, const char* path,
   784	    const vela_header_t* extra_headers,
   785	    const char* json_body,
   786	    char* resp_buf, size_t resp_cap)
   787	{
   788	    /* Build a merged header list: Content-Type first, then caller extras */
   789	    const int MAX_HDRS = 32;
   790	    vela_header_t merged[MAX_HDRS];
   791	    int n = 0;
   792	
   793	    merged[n++] = (vela_header_t) { "Content-Type", "application/json" };
   794	
   795	    if (extra_headers) {
   796	        for (const vela_header_t* h = extra_headers; h->name && n < MAX_HDRS - 1; h++) {
   797	            merged[n++] = *h;
   798	        }
   799	    }
   800	    merged[n] = (vela_header_t) { NULL, NULL };
   801	
   802	    size_t body_len = json_body ? strlen(json_body) : 0;
   803	    return vela_https_request(host, port, "POST", path, merged,
   804	        json_body, body_len, resp_buf, resp_cap, NULL);
   805	}
