   807	int vela_https_head_date(const char* host, const char* port, const char* path,
   808	    char* date_out, size_t date_cap)
   809	{
   810	    tls_ctx_t ctx;
   811	    int ret;
   812	
   813	    if ((ret = tls_ctx_connect(&ctx, host, port)) != 0) {
   814	        tls_ctx_free(&ctx);
   815	        return ret;
   816	    }
   817	
   818	    if ((ret = tls_write_request(&ctx, "HEAD", host, path, NULL, NULL, 0)) != 0) {
   819	        tls_ctx_free(&ctx);
   820	        return ret;
   821	    }
   822	
   823	    /* Read raw response until end of headers (\r\n\r\n) */
   824	    char hdr_buf[2048];
   825	    int total = 0;
   826	    while (total < (int)sizeof(hdr_buf) - 1) {
   827	        ret = mbedtls_ssl_read(&ctx.ssl,
   828	            (unsigned char*)hdr_buf + total,
   829	            sizeof(hdr_buf) - 1 - total);
   830	        if (ret == MBEDTLS_ERR_SSL_WANT_READ)
   831	            continue;
   832	        if (ret <= 0)
   833	            break;
   834	        total += ret;
   835	        hdr_buf[total] = '\0';
   836	        if (strstr(hdr_buf, "\r\n\r\n"))
   837	            break;
   838	    }
   839	    tls_ctx_free(&ctx);
   840	
   841	    if (total <= 0)
   842	        return VELA_TLS_ERR_READ;
   843	
   844	    /* Find Date: header (case-insensitive prefix search) */
   845	    char* p = strcasestr(hdr_buf, "\r\nDate: ");
   846	    if (!p)
   847	        return VELA_TLS_ERR_READ;
   848	    p += 8; /* skip \r\nDate:  */
   849	    char* eol = strstr(p, "\r\n");
   850	    if (!eol)
   851	        return VELA_TLS_ERR_READ;
   852	
   853	    size_t dlen = (size_t)(eol - p);
   854	    if (dlen >= date_cap)
   855	        dlen = date_cap - 1;
   856	    memcpy(date_out, p, dlen);
   857	    date_out[dlen] = '\0';
   858	    return 0;
   859	}
